export interface Point {
  readonly x: number;
  readonly y: number;
}

function finite(...values: number[]): void {
  if (values.some((value) => !Number.isFinite(value))) {
    throw new RangeError("numeric arguments must be finite");
  }
}

function validBounds(lower: number, upper: number): void {
  finite(lower, upper);
  if (lower >= upper) throw new RangeError("lower must be less than upper");
}

function validFraction(fraction: number): void {
  finite(fraction);
  if (fraction < 0 || fraction > 1) throw new RangeError("fraction must be in [0, 1]");
}

export function wrapHalfOpen(value: number, lower: number, upper: number): number {
  finite(value);
  validBounds(lower, upper);
  if (value < lower) return upper - (lower - value);
  if (value >= upper) return lower + (value - upper);
  return value;
}

export function bound(value: number, lower: number, upper: number): number {
  finite(value);
  validBounds(lower, upper);
  return Math.min(upper, Math.max(lower, value));
}

export function blend(from: number, to: number, fraction: number): number {
  finite(from, to);
  validFraction(fraction);
  return from + (to - from) * fraction;
}

export function cubicPoint(a: Point, b: Point, c: Point, d: Point, fraction: number): Point {
  finite(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y);
  validFraction(fraction);
  const inverse = 1 - fraction;
  const w0 = inverse * inverse * inverse;
  const w1 = 3 * inverse * inverse * fraction;
  const w2 = 3 * inverse * fraction * fraction;
  const w3 = fraction * fraction * fraction;
  return {
    x: w0 * a.x + w1 * b.x + w2 * c.x + w3 * d.x,
    y: w0 * a.y + w1 * b.y + w2 * c.y + w3 * d.y
  };
}

export function smoothStep(fraction: number): number {
  validFraction(fraction);
  return fraction * fraction * (3 - 2 * fraction);
}

export function selectOwn<T extends object, K extends keyof T>(source: T, keys: readonly K[]): Pick<T, K> {
  const result: Partial<Pick<T, K>> = {};
  const seen = new Set<PropertyKey>();
  for (const key of keys) {
    if (!seen.has(key) && Object.prototype.hasOwnProperty.call(source, key)) {
      result[key] = source[key];
      seen.add(key);
    }
  }
  return result as Pick<T, K>;
}

