import { wrapHalfOpen, bound, blend, cubicPoint, smoothStep, selectOwn } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

equal(wrapHalfOpen(10, 0, 10), 0, 'upper endpoint wraps to lower');
equal(wrapHalfOpen(-1, 0, 10), 9, 'negative values wrap backward');
equal(wrapHalfOpen(1234, 2, 7), 4, 'large values wrap into the half-open interval');
equal(bound(-3, -2, 4), -2, 'bound clamps below lower');
equal(bound(8, -2, 4), 4, 'bound clamps above upper');
equal(bound(1, -2, 4), 1, 'bound preserves an interior value');
equal(blend(10, 20, 0), 10, 'blend supports zero fraction');
equal(blend(10, 20, 1), 20, 'blend supports unit fraction');
equal(blend(10, 20, 0.25), 12.5, 'blend interpolates');
equal(smoothStep(0), 0, 'smoothStep starts at zero');
equal(smoothStep(0.5), 0.5, 'smoothStep midpoint');
equal(smoothStep(1), 1, 'smoothStep ends at one');

const a = { x: 0, y: 0 };
const b = { x: 1, y: 2 };
const c = { x: 2, y: 2 };
const d = { x: 3, y: 0 };
const snapshots = JSON.stringify([a, b, c, d]);
deepEqual(cubicPoint(a, b, c, d, 0.5), { x: 1.5, y: 1.5 }, 'cubic Bézier point is calculated per coordinate');
equal(JSON.stringify([a, b, c, d]), snapshots, 'cubicPoint does not mutate points');
assert(cubicPoint(a, b, c, d, 0) !== a, 'cubicPoint returns a new point at the boundary');

expectRange(() => wrapHalfOpen(NaN, 0, 1), 'wrap rejects NaN');
expectRange(() => wrapHalfOpen(0, 1, 1), 'wrap rejects equal bounds');
expectRange(() => wrapHalfOpen(0, 2, 1), 'wrap rejects reversed bounds');
expectRange(() => bound(0, 0, Infinity), 'bound rejects non-finite bounds');
expectRange(() => bound(0, 2, 1), 'bound rejects reversed bounds');
expectRange(() => blend(Infinity, 1, 0.5), 'blend rejects non-finite endpoints');
expectRange(() => blend(0, 1, -0.01), 'blend rejects fractions below zero');
expectRange(() => blend(0, 1, 1.01), 'blend rejects fractions above one');
expectRange(() => smoothStep(NaN), 'smoothStep rejects NaN');
expectRange(() => smoothStep(-1), 'smoothStep rejects out-of-range fractions');
expectRange(() => cubicPoint(a, b, { x: Infinity, y: 0 }, d, 0.5), 'cubicPoint validates every coordinate');
expectRange(() => cubicPoint(a, b, c, d, 2), 'cubicPoint validates its fraction');

const prototype = { inherited: 'prototype' };
const source = Object.create(prototype) as {
  first: number;
  second: number;
  inherited?: string;
  absent?: string;
  nested: { value: number };
};
source.first = 1;
source.second = 2;
source.nested = { value: 3 };
const selected = selectOwn(source, ['second', 'inherited', 'first', 'second', 'absent', 'nested']);
deepEqual(Object.keys(selected), ['second', 'first', 'nested'], 'selectOwn ignores inherited and missing keys, deduplicates, and preserves request order');
deepEqual(selected, { second: 2, first: 1, nested: source.nested }, 'selectOwn copies requested own values');
assert(selected !== source, 'selectOwn returns a new object');
assert(selected.nested === source.nested, 'selectOwn is shallow');
deepEqual(selectOwn(source, []), {}, 'empty key list produces an empty object');

